import json, hashlib
from pathlib import Path
P=Path('packet.json'); p=json.loads(P.read_text()); entries={x['source_id']:x for x in p['entries']}; texts={k:v['text'] for k,v in entries.items()}
units=[]; relations=[]

def ev(s,q,start=0):
    i=texts[s].index(q,start)
    return {'source_id':s,'span':{'start':i,'end':i+len(q),'quote':q}}

def unit(uid,s,q,role='statement',grammar='regulative',speech='proposed',scope='case_specific',parse='literal',force='recommendation',itype='undetermined',standing='text_only',rationale='',target='operational',observed='operational',level='',alternative='',confidence='clear',uncertainty='',quotation='none',markup='plain',parent=None,flags=None):
    u={'unit_id':uid,**ev(s,q),'parent_unit_id':parent,'record_role':role,'grammar':grammar,'speech_act':speech,'scope':scope,'parse_mode':parse,'deontic_force':force,'components':[],
       'institution':{'type':itype,'standing':standing,'dispute_present':False,'rationale':rationale,'evidence':[],'recognition':[],'authority_evidence':[]},
       'statement_target_level':target,'observed_action_level':observed,'level_rationale':level,'level_alternatives':[],
       'complexity_flags':flags or ['none'],'alternative_interpretation':alternative,'confidence':confidence,'uncertainty_reason':uncertainty,
       'presentation':{'quotation':quotation,'markup':markup,'rationale':'Presentation follows the supplied occurrence; no edit-history inference.'},'disposition_events':[]}
    if role!='statement':
        u.update(grammar='not_institutional',statement_target_level='not_applicable',deontic_force='nondeontic')
        u['institution'].update(type='not_applicable',standing='not_applicable')
        if role=='container':u.update(observed_action_level='not_applicable',speech_act='other')
    units.append(u);return u

def comp(u,sym,text,q=None,basis='explicit',role='local',note='',s=None):
    sid=s or u['source_id'];q=q or text
    st=u['span']['start'] if sid==u['source_id'] and q in u['span']['quote'] else 0
    c={'symbol':sym,'text':text,'basis':basis,'evidence':[ev(sid,q,st)],'occurrence_role':role,'inference_note':note};u['components'].append(c);return c

def rec(u,kind,target,evidence,rationale,basis='explicit'):
    u['institution']['recognition'].append({'kind':kind,'target':target,'basis':basis,'evidence':evidence,'rationale':rationale})
def disp(u,kind,target,evidence,rationale,basis='explicit'):
    u['disposition_events'].append({'kind':kind,'target':target,'basis':basis,'evidence':evidence,'rationale':rationale})
def rel(fr,to,typ,evidence,rationale,basis='context_inferred',logic='not_applicable'):
    relations.append({'from_unit_id':fr,'to_unit_id':to,'type':typ,'basis':basis,'evidence':evidence,'rationale':rationale,'logic_scope':logic})

